import { PASSWORD, USERS, expect, test } from "../../fixtures";

test.describe("sign in with unknown email", () => {
  test(
    "unknown email is rejected with 401 invalid_credentials",
    { tag: "@AUTH-03" },
    async ({ request }) => {
      // Act
      const response = await request.post("/api/auth/login", {
        data: { email: "nobody@northwind.test", password: PASSWORD },
      });

      // Assert
      expect(response.status()).toBe(401);
      const body = await response.json();
      expect(body.error.code).toBe("invalid_credentials");
    },
  );

  test(
    "unknown email gets the same status and error code as a wrong password",
    { tag: "@AUTH-03" },
    async ({ request }) => {
      // Arrange
      const unknown = await request.post("/api/auth/login", {
        data: { email: "nobody@northwind.test", password: PASSWORD },
      });
      const wrongPassword = await request.post("/api/auth/login", {
        data: { email: USERS.member, password: "wrong-password" },
      });

      // Assert
      expect(unknown.status()).toBe(401);
      expect(wrongPassword.status()).toBe(401);
      expect(unknown.status()).toBe(wrongPassword.status());

      const unknownBody = await unknown.json();
      const wrongBody = await wrongPassword.json();
      expect(unknownBody.error.code).toBe("invalid_credentials");
      expect(wrongBody.error.code).toBe("invalid_credentials");
      expect(unknownBody.error.code).toBe(wrongBody.error.code);
    },
  );
});
